static const sa1em_list k_lists[8] = {
    { 0, 0u, 107u, k_sonic },
    { 2, 0u, 140u, k_tails },
    { 3, 0u, 122u, k_knuckles },
    { 5, 0u, 105u, k_amy },
    { 6, 0u, 89u, k_gamma },
    { 7, 0u, 96u, k_big },
    { 0, 1u, 119u, k_sonic_super },
    { 8, 0u, 92u, k_supersonic },
};

const sa1em_list *sa1em_list_of(int32_t kind, uint32_t form)
{
    uint32_t i;
    if (kind == 8) {
        form = 0u;                  /* kind 8 is always Super: one list */
    }
    for (i = 0; i < (uint32_t)(sizeof k_lists / sizeof k_lists[0]); i++) {
        if (k_lists[i].kind == kind && k_lists[i].form == form) {
            return &k_lists[i];
        }
    }
    return NULL;
}
